import{_ as t,o as a,c as e,Q as d}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"Birthday Party Invitation (Textbook Listening Exercise)","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/16-anna-birthday-party-invitation.md","filePath":"en/more/maltese/practice/emails/16-anna-birthday-party-invitation.md"}'),r={name:"en/more/maltese/practice/emails/16-anna-birthday-party-invitation.md"},o=d('<h1 id="birthday-party-invitation-textbook-listening-exercise" tabindex="-1">Birthday Party Invitation (Textbook Listening Exercise) <a class="header-anchor" href="#birthday-party-invitation-textbook-listening-exercise" aria-label="Permalink to &quot;Birthday Party Invitation (Textbook Listening Exercise)&quot;">​</a></h1><p><strong>Scenario:</strong> Anna writes an email to Maria to invite her to her 15th birthday party at Għadira Bay. This is the original textbook email from the PDF, including the listening gap-fill options in brackets.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a><strong>Mingħand (From):</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data (Date):</strong> 30 ta&#39; Ġunju, 2023 <strong>Suġġett (Subject):</strong> Festin ta&#39; għeluq snini</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 30 ta&#39; Ġunju, 2023 <strong>Suġġett:</strong> Festin ta&#39; għeluq snini</p><p>Ħelow Maria!</p><p>Nispera li tinsab tajba. Bħalma taf, (ilbieraħ / dalwaqt / sena oħra) se nagħlaq 15-il sena u qed nibgħatek din l-ittra elettronika sabiex nistednek għall-festin ta&#39; għeluq snini.</p><p>Il-festin se jkun nhar (il-ġimgħa l-oħra / ix-xahar id-dieħel / il-Ġimgħa 14 ta&#39; Lulju).</p><p>Fis- (tmienja ta&#39; flgħaxija / sitta ta&#39; flgħodu / sitta ta&#39; flgħaxija) se niltaqgħu (quddiem / fuq / taħt) il-knisja biex minn hemm niġru bil-van kollha f&#39;daqqa li se joħodna l-bajja tal-Għadira.</p><p>Fil-festin se jkun hemm ħafna ikel, xorb, logħob u mużika! Tinsiex tiġi bil-malja u ġġib xugaman għax xi qabża l-baħar ma tonqosx!</p><p>Jekk jogħġbok agħtini risposta sa (bħal-lum ġimgħa / xahar ieħor).</p><p>Nispera li narak ħalli nieħdu gost flimkien!</p><p>Ċaw! Anna</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a></td><td>email address</td><td>The recipient&#39;s address</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>Translation:</strong> From: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>email address</td><td>The sender&#39;s address</td></tr></tbody></table><p><strong>Malti:</strong> Data: 30 ta&#39; Ġunju, 2023</p><p><strong>Translation:</strong> Date: 30 June 2023</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>30</td><td>thirty</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ġunju</td><td>June</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Festin ta&#39; għeluq snini</p><p><strong>Translation:</strong> Subject: My Birthday Celebration</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field; printed <code>Suggett</code> in the source</td></tr><tr><td>Festin</td><td>celebration; little party</td><td>Diminutive loanword</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>għeluq</td><td>birthday</td><td>Literally &quot;closing&quot;; <code>għeluq snin</code> = birthday</td></tr><tr><td>snini</td><td>my years; my birthday</td><td><code>snin</code> (years) + <code>-i</code> (my)</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Ħelow Maria!</p><p><strong>Translation:</strong> Hello Maria!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ħelow</td><td>hello</td><td>Informal greeting, loanword</td></tr><tr><td>Maria</td><td>Maria</td><td>Name</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tinsab tajba.</p><p><strong>Translation:</strong> I hope you are well.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular</td></tr><tr><td>li</td><td>that</td><td>Conjunction</td></tr><tr><td>tinsab</td><td>you are</td><td>Second-person form of <code>tinsab</code> &quot;to be located / to feel&quot;</td></tr><tr><td>tajba</td><td>well; good</td><td>Feminine singular adjective</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Bħalma taf, (ilbieraħ / dalwaqt / sena oħra) se nagħlaq 15-il sena u qed nibgħatek din l-ittra elettronika sabiex nistednek għall-festin ta&#39; għeluq snini.</p><p><strong>Translation:</strong> As you know, (yesterday / soon / another year) I am turning 15, and I am sending you this email to invite you to my birthday party.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Bħalma</td><td>as; just as</td><td><code>bħal</code> + <code>ma</code></td></tr><tr><td>taf</td><td>you know</td><td>Second-person singular</td></tr><tr><td>ilbieraħ</td><td>yesterday</td><td>Listening option 1</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Listening option 2</td></tr><tr><td>sena oħra</td><td>another year</td><td>Listening option 3</td></tr><tr><td>se</td><td>will</td><td>Future marker</td></tr><tr><td>nagħlaq</td><td>I turn (age)</td><td>Literally &quot;I close&quot;; reaching an age</td></tr><tr><td>15-il sena</td><td>15 years old</td><td>Numeral + <code>-il</code> + <code>sena</code></td></tr><tr><td>qed</td><td>am (progressive)</td><td>Progressive marker</td></tr><tr><td>nibgħatek</td><td>I send you</td><td><code>nibgħat</code> + <code>-ek</code> (you)</td></tr><tr><td>din</td><td>this</td><td>Feminine demonstrative</td></tr><tr><td>l-ittra elettronika</td><td>the email</td><td><code>ittra</code> (letter) + <code>elettronika</code> (electronic)</td></tr><tr><td>sabiex</td><td>in order to</td><td>Formal conjunction</td></tr><tr><td>nistednek</td><td>I invite you</td><td><code>nistedin</code> + <code>-ek</code></td></tr><tr><td>għall-festin</td><td>to the party</td><td>Contracted <code>għal</code> + <code>il-festin</code></td></tr><tr><td>ta&#39; għeluq snini</td><td>of my birthday</td><td><code>għeluq</code> (birthday) + <code>snin</code> (years) + <code>-i</code> (my)</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Il-festin se jkun nhar (il-ġimgħa l-oħra / ix-xahar id-dieħel / il-Ġimgħa 14 ta&#39; Lulju).</p><p><strong>Translation:</strong> The party will be on (next week / next month / Friday 14 July).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Il-festin</td><td>the party</td><td><code>festin</code> (little party), loanword</td></tr><tr><td>se jkun</td><td>will be</td><td>Future construction</td></tr><tr><td>nhar</td><td>on the day of</td><td>Literally &quot;day&quot;</td></tr><tr><td>il-ġimgħa l-oħra</td><td>the other week; next week</td><td>Listening option 1</td></tr><tr><td>ix-xahar id-dieħel</td><td>the coming month; next month</td><td>Listening option 2</td></tr><tr><td>il-Ġimgħa 14 ta&#39; Lulju</td><td>Friday 14 July</td><td>Listening option 3</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Fis- (tmienja ta&#39; flgħaxija / sitta ta&#39; flgħodu / sitta ta&#39; flgħaxija) se niltaqgħu (quddiem / fuq / taħt) il-knisja biex minn hemm niġru bil-van kollha f&#39;daqqa li se joħodna l-bajja tal-Għadira.</p><p><strong>Translation:</strong> At (8 pm / 6 am / 6 pm) we will meet (in front of / above / below) the church, and from there we will all drive together by van to Għadira Bay.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>tmienja ta&#39; flgħaxija</td><td>eight in the evening</td><td>Listening option 1 (<code>filgħaxija</code>)</td></tr><tr><td>sitta ta&#39; flgħodu</td><td>six in the morning</td><td>Listening option 2 (<code>filgħodu</code>)</td></tr><tr><td>sitta ta&#39; flgħaxija</td><td>six in the evening</td><td>Listening option 3</td></tr><tr><td>quddiem</td><td>in front of</td><td>Listening option 1 (position)</td></tr><tr><td>fuq</td><td>above; on top</td><td>Listening option 2</td></tr><tr><td>taħt</td><td>below; under</td><td>Listening option 3</td></tr><tr><td>il-knisja</td><td>the church</td><td>Feminine noun with the definite article</td></tr><tr><td>biex</td><td>in order to</td><td>Purpose conjunction</td></tr><tr><td>minn hemm</td><td>from there</td><td>Place phrase</td></tr><tr><td>niġru</td><td>we drive quickly</td><td>First-person plural of <code>iġri</code> &quot;to run / hurry&quot;</td></tr><tr><td>bil-van</td><td>by van</td><td>Contracted <code>b&#39;</code> + <code>il-van</code></td></tr><tr><td>kollha f&#39;daqqa</td><td>all together</td><td><code>kollha</code> (all) + <code>f&#39;daqqa</code> (at once)</td></tr><tr><td>se joħodna</td><td>will take us</td><td><code>jieħu</code> (take) + <code>-na</code> (us)</td></tr><tr><td>l-bajja tal-Għadira</td><td>Għadira Bay</td><td><code>bajja</code> (bay) + <code>tal-</code> (of) + <code>Għadira</code> (place name)</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Fil-festin se jkun hemm ħafna ikel, xorb, logħob u mużika!</p><p><strong>Translation:</strong> At the party there will be lots of food, drink, games and music!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Fil-festin</td><td>at the party</td><td>Contracted <code>f&#39;</code> + <code>il-festin</code></td></tr><tr><td>se jkun hemm</td><td>there will be</td><td>Existential construction</td></tr><tr><td>ħafna</td><td>lots of</td><td>Quantifier</td></tr><tr><td>ikel</td><td>food</td><td>Masculine noun</td></tr><tr><td>xorb</td><td>drink</td><td>Noun</td></tr><tr><td>logħob</td><td>games</td><td>Noun</td></tr><tr><td>mużika</td><td>music</td><td>Loanword</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Tinsiex tiġi bil-malja u ġġib xugaman għax xi qabża l-baħar ma tonqosx!</p><p><strong>Translation:</strong> Don&#39;t forget to come in your swimsuit and bring a towel, because a dip in the sea is a must!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tinsiex</td><td>don&#39;t forget</td><td><code>tinsa</code> + <code>x</code>, negative imperative</td></tr><tr><td>tiġi</td><td>you come</td><td>Second-person singular</td></tr><tr><td>bil-malja</td><td>in a swimsuit</td><td>Contracted <code>b&#39;</code> + <code>il-malja</code> (swimsuit)</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>ġġib</td><td>you bring</td><td>Second-person singular</td></tr><tr><td>xugaman</td><td>towel</td><td>Loanword</td></tr><tr><td>għax</td><td>because</td><td>Causal conjunction</td></tr><tr><td>xi</td><td>a; some</td><td>Determiner</td></tr><tr><td>qabża l-baħar</td><td>a jump in the sea</td><td><code>qabża</code> (jump) + <code>l-baħar</code> (sea)</td></tr><tr><td>ma tonqosx</td><td>won&#39;t be missing</td><td><code>ma</code> + <code>tonqos</code> + <code>x</code> negation; idiom &quot;a must&quot;</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok agħtini risposta sa (bħal-lum ġimgħa / xahar ieħor).</p><p><strong>Translation:</strong> Please give me a reply within (a week from today / a month&#39;s time).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>please</td><td>Literally &quot;if it pleases you&quot;</td></tr><tr><td>agħtini</td><td>give me</td><td><code>agħti</code> (give) + <code>-ni</code> (me)</td></tr><tr><td>risposta</td><td>reply; answer</td><td>Loanword</td></tr><tr><td>sa</td><td>by; until</td><td>Preposition</td></tr><tr><td>bħal-lum ġimgħa</td><td>a week from today</td><td>Listening option 1 (one OCR option is unclear, possibly <code>il-biċċa l-oħra</code>)</td></tr><tr><td>xahar ieħor</td><td>another month; a month later</td><td>Listening option 2</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li narak ħalli nieħdu gost flimkien!</p><p><strong>Translation:</strong> I hope to see you so that we can have fun together!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular</td></tr><tr><td>li</td><td>that</td><td>Conjunction</td></tr><tr><td>narak</td><td>I see you</td><td><code>nara</code> + <code>-k</code> (you)</td></tr><tr><td>ħalli</td><td>so that</td><td>Colloquial conjunction</td></tr><tr><td>nieħdu gost</td><td>we have fun</td><td><code>ieħu gost</code> idiom &quot;to enjoy&quot;</td></tr><tr><td>flimkien</td><td>together</td><td>Adverb</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Ċaw!</p><p><strong>Translation:</strong> Bye!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ċaw</td><td>bye</td><td>Informal farewell</td></tr></tbody></table><p><strong>Malti:</strong> Anna</p><p><strong>Translation:</strong> Anna (signature)</p><h2 id="formal-vs-informal-openings-and-closings-from-the-same-pdf-page" tabindex="-1">Formal vs Informal Openings and Closings (from the same PDF page) <a class="header-anchor" href="#formal-vs-informal-openings-and-closings-from-the-same-pdf-page" aria-label="Permalink to &quot;Formal vs Informal Openings and Closings (from the same PDF page)&quot;">​</a></h2><table><thead><tr><th>Item</th><th>Formal (Formali)</th><th>Informal (Informali)</th></tr></thead><tbody><tr><td>Opening</td><td>Għażiż/a Sur ..., Sinjura ... (Dear Mr ... / Mrs ...)</td><td>Ħelow, Ħaw&#39;, Bongu... (Hello, Hi, Good morning...)</td></tr><tr><td>Closing</td><td>Saħħa, Tislijiet, Dejjem tiegħek (Take care, Regards, Yours truly)</td><td>Ċaw, Sellili, Narak! (Bye, say hello for me, See you!)</td></tr></tbody></table>',63),n=[o];function i(l,s,h,g,m,c){return a(),e("div",null,n)}const p=t(r,[["render",i]]);export{b as __pageData,p as default};
